        `,foundIn:"Livre de base"},{name:"Clameur",level:0,tradition:Da,type:"Utilitaire",currentUses:0,target:"Un point dans un espace situ\xE9 jusqu\u2019\xE0 port\xE9e moyenne",duration:"1 min",effect:`
